 if(game.result&&!document.querySelector('#ending').open){document.querySelector('#endingTitle').textContent=game.result==='victory'?'Sơn hà quy một mối':'Ngọn cờ chưa tắt';document.querySelector('#endingText').textContent=game.result==='victory'?'Mười hai vùng đất đã quy phục. Bạn đã hoàn thành chiến dịch demo.':'Hoa Lư đã thất thủ. Hãy nâng cấp, giữ đội hình và thử một chiến lược khác.';document.querySelector('#ending').showModal();}
