function selectArmy(){panelMode='orders';selectedNode=null;buildMode=null;selected=game.units.filter(u=>u.hp>0&&u.owner===0&&!u.embarked&&!U[u.kind].naval&&u.kind!=='worker').map(u=>u.id);updateUI();}
function selectWorkers(idle=false){panelMode='orders';buildMode=null;selected=game.units.filter(u=>u.hp>0&&u.owner===0&&u.kind==='worker'&&!u.embarked&&(!idle||!u.work)).map(u=>u.id);updateUI();}
function pick(p){const q=screen(p);return [...game.units.filter(u=>!u.embarked),...game.buildings,...game.nodes.filter(n=>!n.farm)].filter(e=>{if(!(e.hp>0||e.entity==='resource'))return false;const s=screen(e),building=e.entity==='building'&&!e.wall,r=e.wall?.55:building?1.4:e.entity==='resource'?.6:U[e.kind]?.naval?.8:.35;return Math.abs(q.x-s.x)<scale*r&&q.y>s.y-scale*(e.wall?(e.kind==='walltower'?2.6:1.4):building?1.8:e.kind==='wood'?1.4:(e.kind==='elephant'||e.kind==='armoredElephant')?1.9:U[e.kind]?.hero?(sprites.headHeight(e,game)+.1):1.2)&&q.y<s.y+scale*(building?.6:U[e.kind]?.naval?.45:.25);}).sort((a,b)=>((a.entity==='unit'?0:1)-(b.entity==='unit'?0:1))||(b.x+b.y)-(a.x+a.y))[0];}
canvas.addEventListener('pointermove',e=>{pointer=pos(e);camMotion.inside=true;const pan=camMotion.pan;if(pan){if(Math.hypot(pointer.x-pan.x,pointer.y-pan.y)>5)pan.moved=true;const a=LoanArt.unproject(pan,pan.cam,scale,width,height),b=LoanArt.unproject(pointer,pan.cam,scale,width,height);cam.x=Math.max(0,Math.min(W,pan.cam.x+a.x-b.x));cam.y=Math.max(0,Math.min(H,pan.cam.y+a.y-b.y));}});canvas.addEventListener('pointerleave',()=>camMotion.inside=false);canvas.addEventListener('auxclick',e=>{if(e.button===1)e.preventDefault();});
