document.querySelector('#handbookButton').onclick=()=>{divineCrossbowBook();const articles=[...document.querySelectorAll('#bookContent article')],tech=articles.find(a=>a.querySelector('h4')?.textContent.startsWith('Bí pháp Nỏ Thần'));if(tech){const small=tech.querySelector('small');if(small)small.textContent='Trường Bắn & Cơ Khí III · 220 Gỗ + 180 Vàng + 180 Sắt · 45s · cần Đại Bản Doanh III và Đầu tên thép II.';}const galleryHeading=[...document.querySelectorAll('#bookContent h3')].find(h=>h.textContent.startsWith('Binh chủng Việt cổ')),grid=galleryHeading?.parentElement?.querySelector('.book-grid');if(grid&&!grid.querySelector('[data-unit="divineCrossbow"]')){const card=document.createElement('article'),cv=document.createElement('canvas'),h=document.createElement('h4'),p=document.createElement('p');card.dataset.unit='divineCrossbow';cv.width=260;cv.height=150;cv.style.cssText='width:100%;height:140px;object-fit:contain;background:radial-gradient(ellipse at center,#59644a,#29392c);border-radius:4px';const unit={id:112,kind:'divineCrossbow',x:0,y:0,rank:3,angle:0,hp:U.divineCrossbow.hp,maxHP:U.divineCrossbow.hp};LoanArt.unit(cv.getContext('2d'),unit,game,()=>({x:125,y:125}),70,false,colors[0]);h.textContent=U.divineCrossbow.name;p.textContent='Binh đoàn đặc biệt tối hậu · nỏ cánh kép, tay quay, bắn 4 tia xuyên giáp; trang phục đổi theo triều đại và giới hạn 6 quân.';card.append(cv,h,p);grid.append(card);}};
