document.querySelector('#help').onclick=()=>{game.paused=true;factionSelect.disabled=started;mapSelect.disabled=started;document.querySelector('#start').textContent=started?'TIẾP TỤC TRẬN':'DỰNG CỜ KHỞI NGHĨA';document.querySelector('#intro').showModal();};document.querySelector('#start').onclick=()=>{if(!started){const detail=game.visualDetail;const setup=(typeof matchSetup==='function'&&!(typeof multi!=='undefined'&&multi.active))?matchSetup():null;game=new Game(factionSelect.value,Math.random,mapSelect.value,setup);game.visualDetail=detail;selected=[];selectedNode=null;buildMode=null;attackMode=false;homeCam();game.factionSlots.forEach((id,owner)=>LORDS[owner]=Loan12.FACTIONS[id].name);if(game.faction&&U.dinh)U.dinh.name=game.faction(0).name;lastDetailsKey='';lastLordsKey='';document.querySelector('.map-heading h2').textContent='Ngọn cờ '+game.faction().region;document.querySelector('.map-heading .eyebrow').textContent=game.mapProfile.name.toUpperCase();document.querySelector('#home').textContent='⌂ Căn cứ';factionSelect.disabled=true;mapSelect.disabled=true;}started=true;game.paused=false;document.querySelector('#intro').close();updateUI();toast(game.faction().name+' — '+game.mapProfile.name);};
