document.querySelector('#restart').onclick=()=>{game.paused=true;started=false;selected=[];selectedNode=null;buildMode=null;attackMode=false;panelMode='orders';homeCam();cam.zoom=cam.targetZoom=1.15;camMotion.anchor=null;camMotion.vx=camMotion.vy=0;updateScale();keys.clear();factionSelect.disabled=false;mapSelect.disabled=false;document.querySelector('#start').textContent='DỰNG CỜ KHỞI NGHĨA';document.querySelector('#ending').close();document.querySelector('#intro').showModal();};
for(let d of document.querySelectorAll('dialog'))d.addEventListener('cancel',e=>e.preventDefault());
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
function updateCamera(dt){// eased pan: keys + screen-edge scroll, velocity smoothed for an RTS feel
 let ix=((keys.has('KeyD')||keys.has('ArrowRight'))?1:0)-((keys.has('ArrowLeft')||keys.has('KeyA')&&!selected.length)?1:0),iy=((keys.has('KeyS')||keys.has('ArrowDown'))?1:0)-((keys.has('KeyW')||keys.has('ArrowUp'))?1:0);const edge=14;if(started&&camMotion.inside&&!drag&&!camMotion.pan&&document.hasFocus()){if(pointer.x<edge)ix=-1;else if(pointer.x>width-edge)ix=1;if(pointer.y<edge)iy=-1;else if(pointer.y>height-edge)iy=1;}
 const speed=13/cam.zoom,ease=1-Math.exp(-dt*10);camMotion.vx+=(ix*speed-camMotion.vx)*ease;camMotion.vy+=(iy*speed-camMotion.vy)*ease;const dx=camMotion.vx*dt,dy=camMotion.vy*dt;cam.x+=dy+dx/2;cam.y+=dy-dx/2;
 const tz=cam.targetZoom||cam.zoom;if(Math.abs(tz-cam.zoom)>1e-4){cam.zoom+=(tz-cam.zoom)*(1-Math.exp(-dt*12));if(Math.abs(tz-cam.zoom)<1e-3)cam.zoom=tz;updateScale();const a=camMotion.anchor;if(a){const now=LoanArt.unproject(a.screen,cam,scale,width,height);cam.x+=a.world.x-now.x;cam.y+=a.world.y-now.y;}}else camMotion.anchor=null;
 cam.x=Math.max(0,Math.min(W,cam.x));cam.y=Math.max(0,Math.min(H,cam.y));}
function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(started)game.tick(dt);if(fx){const gt=game.time||0;fx.update(game,fxClock===null?0:Math.max(0,Math.min(.1,gt-fxClock)));fxClock=gt;}if(!document.querySelector('dialog[open]'))updateCamera(dt);uiClock+=dt;if(uiClock>.3){updateUI();uiClock=0;}render();requestAnimationFrame(frame);}
window.addEventListener('resize',resize);resize();updateUI();document.querySelector('#intro').showModal();requestAnimationFrame(frame);
